#!/usr/bin/env bash
# Re-apply the Personae release-signing patch to the generated android/ project.
#
# WHY THIS EXISTS: `android/` is generated by `npx expo prebuild` and is git-ignored, so a fresh
# prebuild (or a re-clone) restores the template's release buildType, which signs the "release"
# variant with the DEBUG keystore. This script puts the release keystore back, idempotently.
#
# It only reads the keystore path/password from the environment at build time — nothing secret is
# ever written into the repository.
#
#   bash scripts/patch-android-signing.sh
#
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
GRADLE="$ROOT/android/app/build.gradle"

if [ ! -f "$GRADLE" ]; then
  echo "android/app/build.gradle not found — run: npx expo prebuild -p android" >&2
  exit 1
fi

if grep -q 'PERSONAE_STORE_FILE' "$GRADLE"; then
  echo "already patched: $GRADLE"
  exit 0
fi

python3 - "$GRADLE" <<'PY'
import sys

path = sys.argv[1]
src = open(path).read()

old_signing = """    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }"""

new_signing = """    signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        // Personae release signing. The keystore and its password live OUTSIDE this repository
        // (~/.personae-android/) and reach the build only as environment variables, so neither the
        // key file nor its password is ever committed or written into the repo.
        release {
            def personaeStore = System.getenv("PERSONAE_STORE_FILE")
            if (personaeStore) {
                storeFile file(personaeStore)
                storePassword System.getenv("PERSONAE_STORE_PASSWORD")
                keyAlias System.getenv("PERSONAE_KEY_ALIAS") ?: "personae"
                keyPassword System.getenv("PERSONAE_KEY_PASSWORD")
            }
        }
    }"""

old_release = """        release {
            // Caution! In production, you need to generate your own keystore file.
            // see https://reactnative.dev/docs/signed-apk-android.
            signingConfig signingConfigs.debug"""

new_release = """        release {
            // Release-signed with the Personae keystore when it is supplied, else DEBUG-signed with a
            // loud warning — never silently shipped as release-signed when it is not.
            def personaeStore = System.getenv("PERSONAE_STORE_FILE")
            if (personaeStore && file(personaeStore).exists()) {
                signingConfig signingConfigs.release
                println "Personae: release build signed with ${personaeStore}"
            } else {
                println "Personae WARNING: PERSONAE_STORE_FILE missing or unreadable — this build is DEBUG-signed"
                signingConfig signingConfigs.debug
            }"""

for old, new in ((old_signing, new_signing), (old_release, new_release)):
    if old not in src:
        print("patch target not found in build.gradle — the Expo template changed; patch by hand", file=sys.stderr)
        sys.exit(1)
    src = src.replace(old, new, 1)

open(path, "w").write(src)
print("patched", path)
PY
